var TAUX={EUR:1,USD:1.08,GBP:0.85,CHF:0.97,CAD:1.47};var TAUX_DATE="";var LAST_DE="EUR",LAST_VERS="USD";
function pairRate(){return TAUX[LAST_VERS]/TAUX[LAST_DE];}
function tauxNote(){var el=document.getElementById("src");var r=pairRate().toFixed(4);if(TAUX_DATE){el.textContent="Taux BCE du "+TAUX_DATE+" : 1 "+LAST_DE+" = "+r+" "+LAST_VERS+".";}else{el.textContent="Taux de secours (hors-ligne) : 1 "+LAST_DE+" ≈ "+r+" "+LAST_VERS+".";}}
try{fetch("https://api.frankfurter.dev/v1/latest?base=EUR&symbols=USD,GBP,CHF,CAD").then(function(r){return r.json();}).then(function(j){if(j&&j.rates&&j.rates.USD){TAUX.USD=j.rates.USD;TAUX.GBP=j.rates.GBP;TAUX.CHF=j.rates.CHF;TAUX.CAD=j.rates.CAD;TAUX_DATE=j.date||"";}tauxNote();}).catch(function(){tauxNote();});}catch(e){tauxNote();}
function conv(){var r=TAUX;var m=parseFloat(document.getElementById("mnt").value)||0;var d=document.getElementById("de").value;var v=document.getElementById("vers").value;LAST_DE=d;LAST_VERS=v;var eur=m/r[d];var out=eur*r[v];document.getElementById("res").innerHTML="<b>"+m+" "+d+" ≈ "+out.toFixed(2)+" "+v+"</b>";tauxNote();}
conv();

function qrPayload(){var t=document.getElementById("qtype").value;if(t==="wifi"){var s=document.getElementById("ssid").value||"";var p=document.getElementById("wpass").value||"";return "WIFI:T:"+(p?"WPA":"nopass")+";S:"+s+";P:"+p+";;";}return document.getElementById("qrtext").value||"test";}
function qrMode(){var w=document.getElementById("qtype").value==="wifi";document.getElementById("w-url").style.display=w?"none":"";document.getElementById("w-wifi").style.display=w?"":"none";document.getElementById("w-pass").style.display=w?"":"none";}
document.getElementById("qtype").addEventListener("change",qrMode);
function genQR(){qrMode();var t=encodeURIComponent(qrPayload());var small="https://api.qrserver.com/v1/create-qr-code/?size=200x200&data="+t;var big="https://api.qrserver.com/v1/create-qr-code/?size=600x600&data="+t;document.getElementById("res").innerHTML="<img id=\"qr-img\" alt=\"QR code\" src=\""+small+"\" style=\"background:#fff;padding:8px;border-radius:8px;max-width:100%\"><br><br><button class=\"action\" onclick=\"dlQR()\">Télécharger le QR (PNG)</button>";window.__qrBig=big;}
function dlQR(){var u=window.__qrBig||"";if(!u){return;}if(typeof fetch==="function"){fetch(u).then(function(r){return r.blob();}).then(function(b){var a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="qrcode.png";document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},500);}).catch(function(){window.open(u,"_blank");});}else{window.open(u,"_blank");}}
genQR();

function factureData(){var m=parseFloat(document.getElementById("f4").value)||0;var t=parseFloat(document.getElementById("f5").value)||0;return {n:document.getElementById("f0").value,a:document.getElementById("f1").value,b:document.getElementById("f2").value,c:document.getElementById("f3").value,m:m,t:t,ttc:m*(1+t/100),d:new Date().toLocaleDateString("fr-FR"),h:new Date().toLocaleTimeString("fr-FR")};}
function factureCard(x){return "<div id=\"facture-print\"><div class=\"inv-card\"><div class=\"inv-top\"><span>FACTURE</span><span>N° "+x.n+" · "+x.d+"</span></div><div class=\"inv-cols\"><div><b>Émetteur</b><br>"+x.a+"</div><div><b>Client</b><br>"+x.b+"</div></div><table class=\"inv-table\"><tr><th>Description</th><th style=\"text-align:right\">Montant</th></tr><tr><td>"+x.c+"</td><td style=\"text-align:right\">"+x.m.toFixed(2)+" €</td></tr><tr><td>TVA ("+x.t+" %)</td><td style=\"text-align:right\">"+(x.ttc-x.m).toFixed(2)+" €</td></tr><tr class=\"inv-total\"><td>Total TTC</td><td style=\"text-align:right\">"+x.ttc.toFixed(2)+" €</td></tr></table><div class=\"hint\">Aperçu généré le "+x.d+" à "+x.h+"</div></div></div>";}
function fact(){var x=factureData();document.getElementById("res").innerHTML=factureCard(x);document.getElementById("res").scrollIntoView({behavior:"smooth",block:"nearest"});}
function downloadFacture(){var x=factureData();if(window.jspdf&&window.jspdf.jsPDF){var doc=new window.jspdf.jsPDF({unit:"mm",format:"a4"});doc.setFontSize(22);doc.text("FACTURE "+x.n,14,20);doc.setFontSize(12);doc.text("Date : "+x.d,14,30);doc.text("De : "+x.a,14,42);doc.text("A : "+x.b,14,50);doc.text("Objet : "+x.c,14,58);doc.text("Total HT : "+x.m.toFixed(2)+" EUR",14,72);doc.text("TVA ("+x.t+" %) : "+(x.ttc-x.m).toFixed(2)+" EUR",14,80);doc.setFontSize(16);doc.text("Total TTC : "+x.ttc.toFixed(2)+" EUR",14,92);doc.save("facture-"+x.n+".pdf");return "pdf";}var doc2="<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><title>Facture "+x.n+"</title></head><body>"+factureRows(x)+"</body></html>";var blob=new Blob([doc2],{type:"text/html"});var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="facture.html";document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},500);return "html";}
function factureRows(x){return "<h1>FACTURE "+x.n+"</h1><p>De : "+x.a+"<br>A : "+x.b+"<br>Objet : "+x.c+"<br>Total TTC : "+x.ttc.toFixed(2)+" EUR</p>";}
fact();

function impotParPart(q){var lim=[11497,29584,84809,180384];var tx=[0,0.11,0.30,0.41,0.45];var imp=0,prev=0;for(var i=0;i<5;i++){var haut=i<4?lim[i]:1e12;var tr=Math.max(0,Math.min(q,haut)-prev);imp+=tr*tx[i];prev=haut;}return imp;}
function calcImp(){var r=parseFloat(document.getElementById("ri").value)||0;var p=parseFloat(document.getElementById("parts").value)||1;var pd=parseFloat(document.getElementById("pd").value)||0;var red=parseFloat(document.getElementById("red").value)||0;var cred=parseFloat(document.getElementById("cred").value)||0;var base=Math.max(0,r-pd);var imp=impotParPart(base/p)*p-red-cred;var msg=imp>=0?"Impôt estimé : <b>"+imp.toFixed(0)+" €</b>":"Impôt : <b>0 €</b> — crédit restitué : <b>"+(-imp).toFixed(0)+" €</b>";document.getElementById("res").innerHTML=msg+"<br>Base imposable : <b>"+base.toFixed(0)+" €</b><br>Taux moyen : <b>"+(r>0?Math.max(0,imp)/r*100:0).toFixed(1)+" %</b>";}
calcImp();

var NN=3;
function addNote(){NN++;var d=document.createElement("div");d.innerHTML="<label>Note <input id=\"n"+NN+"\" type=\"number\" placeholder=\"—\" min=\"0\" max=\"20\"> Coef <input id=\"c"+NN+"\" type=\"number\" value=\"1\" min=\"0\"></label>";document.getElementById("notes-more").appendChild(d);}
function calcMoy(){var s=0,c=0;for(var i=1;i<=NN;i++){var el=document.getElementById("n"+i);if(!el){continue;}var n=parseFloat(el.value);var cel=document.getElementById("c"+i);var k=cel?parseFloat(cel.value)||0:0;if(!isNaN(n)&&k>0){s+=n*k;c+=k;}}if(c===0){document.getElementById("res").innerHTML="Entre au moins une note !";return;}var m=s/c;var men=m>=16?"Très bien":m>=14?"Bien":m>=12?"Assez bien":m>=10?"Passable":"À retravailler";document.getElementById("res").innerHTML="Moyenne : <b>"+m.toFixed(2)+" / 20</b> ("+NN+" matières, coefs total : "+c+")<br>Mention estimée : <b>"+men+"</b>";}
calcMoy();

function cvV(id){return document.getElementById(id).value;}
function loadPhoto(){var f=document.getElementById("cvphoto").files[0];if(!f){return;}var rd=new FileReader();rd.onload=function(e){window.__cvPhoto=e.target.result;cvUpdate();};rd.readAsDataURL(f);}
function cvSec(t,x){if(!x||!x.trim()){return "";}return "<h4 class=\"cv-h\">"+t+"</h4><p>"+x+"</p>";}
function cvUpdate(){var pills=cvV("cvs").split(",").map(function(s){return s.trim();}).filter(Boolean).map(function(s){return "<span class=\"cv-pill\">"+s+"</span>";}).join(" ");var photo=window.__cvPhoto?"<img src=\""+window.__cvPhoto+"\" style=\"width:90px;height:90px;object-fit:cover;border-radius:50%\">":"";document.getElementById("cvprev").innerHTML="<div id=\"cv-print\"><div class=\"cv-head\">"+photo+"<div><h3>"+cvV("cvn")+"</h3><p class=\"cv-title\">"+cvV("cvt")+"</p><p class=\"cv-contact\">"+cvV("cve")+" · "+cvV("cvp")+" · "+cvV("cvv")+(cvV("cvl")?" · "+cvV("cvl"):"")+"</p></div></div>"+cvSec("Profil",cvV("cvr"))+cvSec("Expérience",cvV("cvx"))+cvSec("Formation",cvV("cvf"))+(pills?"<h4 class=\"cv-h\">Compétences</h4><p>"+pills+"</p>":"")+cvSec("Langues",cvV("cvg"))+cvSec("Loisirs",cvV("cvh"))+"</div>";}
cvUpdate();
